CREATE OR REPLACE FUNCTION addams.submit_development(p_key text,p_spec jsonb,p_dependencies uuid[] DEFAULT '{}')
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE j addams.jobs; d uuid; spec jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(734812);
 IF p_key IS NULL OR length(p_key) NOT BETWEEN 1 AND 200 OR jsonb_typeof(p_spec)<>'object'
   OR p_spec->>'contract_sha256' !~ '^[a-f0-9]{64}$' OR NOT p_spec ? 'contract_sha256'
   OR coalesce(p_spec->>'plan_item','')='' OR coalesce(p_spec->>'source_revision','')=''
 THEN RAISE EXCEPTION 'invalid development admission'; END IF;
 IF p_dependencies IS NULL OR array_length(p_dependencies,1)>32 THEN RAISE EXCEPTION 'invalid dependencies'; END IF;
 FOREACH d IN ARRAY p_dependencies LOOP
  IF NOT EXISTS(SELECT 1 FROM addams.jobs WHERE id=d AND job_class='development') THEN
   RAISE EXCEPTION 'missing development prerequisite';
  END IF;
 END LOOP;
 spec := jsonb_build_object('contract',p_spec,'dependencies',to_jsonb(p_dependencies));
 SELECT * INTO j FROM addams.jobs WHERE operation='development.execute' AND idempotency_key=p_key;
 IF FOUND THEN
  IF j.job_spec-'dependency_outputs' IS DISTINCT FROM spec THEN RAISE EXCEPTION 'idempotency conflict'; END IF;
  RETURN j.id;
 END IF;
 SELECT * INTO j FROM addams.submit_job(p_operation=>'development.execute',p_params=>spec,
   p_idempotency_key=>p_key,p_submitted_by=>'operator:development',p_max_attempts=>2,p_default_max_attempts=>2);
 -- Not visible to claimers until this transaction commits. The reconciler releases it.
 UPDATE addams.jobs SET next_attempt_at='infinity' WHERE id=j.id;
 RETURN j.id;
END $$;
REVOKE ALL ON FUNCTION addams.submit_development(text,jsonb,uuid[]) FROM PUBLIC,anon,authenticated,runner_ledger;
GRANT EXECUTE ON FUNCTION addams.submit_development(text,jsonb,uuid[]) TO service_role;

CREATE OR REPLACE FUNCTION addams.release_development()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE j addams.jobs; missing integer; failed integer; outputs jsonb; released integer:=0; blocked integer:=0;
BEGIN
 FOR j IN SELECT * FROM addams.jobs WHERE job_class='development' AND status='pending'
    AND next_attempt_at='infinity' ORDER BY created_at FOR UPDATE SKIP LOCKED LOOP
  SELECT count(*) FILTER(WHERE p.id IS NULL OR p.status<>'completed'
    OR p.result->'output'->>'verification' IS DISTINCT FROM 'accepted'),
    count(*) FILTER(WHERE p.status IN ('failed','cancelled') OR
     (p.status='completed' AND p.result->'output'->>'verification' IS DISTINCT FROM 'accepted')),
    coalesce(jsonb_object_agg(p.id::text,p.result->'output') FILTER(WHERE p.id IS NOT NULL),'{}')
   INTO missing,failed,outputs
   FROM jsonb_array_elements_text(j.job_spec->'dependencies') d
   LEFT JOIN addams.jobs p ON p.id=d.value::uuid;
  IF failed>0 THEN
   PERFORM addams.cancel_job(j.id);
   INSERT INTO addams.job_events(job_id,event_type,payload)
    VALUES(j.id,'dependency_failed','{"reason":"prerequisite did not produce accepted evidence"}');
   blocked:=blocked+1;
  ELSIF missing=0 THEN
   UPDATE addams.jobs SET next_attempt_at=now(),job_spec=job_spec || jsonb_build_object('dependency_outputs',outputs)
    WHERE id=j.id;
   INSERT INTO addams.job_events(job_id,event_type,payload) VALUES(j.id,'dependencies_ready',jsonb_build_object('count',jsonb_array_length(j.job_spec->'dependencies')));
   PERFORM pg_notify('addams_job_notify','development'); released:=released+1;
  END IF;
 END LOOP;
 RETURN jsonb_build_object('released',released,'cancelled_due_to_dependency',blocked);
END $$;
REVOKE ALL ON FUNCTION addams.release_development() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION addams.release_development() TO runner_ledger,service_role;
COMMIT;
