"""Bounded, portable development task contract. No scheduling or model policy."""
import hashlib
import json
from pathlib import PurePosixPath

MAX_BYTES = 131072

def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()).hexdigest()

def path(value):
    if not isinstance(value, str) or not value or '\\' in value or '\x00' in value:
        raise ValueError('invalid path')
    p = PurePosixPath(value)
    if p.is_absolute() or any(x in ('', '.', '..') for x in value.split('/')):
        raise ValueError('path must be relative and normalized')
    return value

def files(value):
    if not isinstance(value, dict) or len(value)>100:
        raise ValueError('files must be a bounded mapping')
    for k,v in value.items():
        path(k)
        if not isinstance(v,str): raise ValueError('file content must be text')
    if len(json.dumps(value).encode())>MAX_BYTES: raise ValueError('file bundle exceeds limit')
    return value

def validate(c):
    if not isinstance(c,dict): raise ValueError('contract required')
    if set(c) != {'version','plan_item','source_revision','files','allowed_paths','worker','checks','timeout_seconds','contract_sha256'}:
        raise ValueError('unknown or missing contract fields')
    if c['version'] != 1: raise ValueError('unsupported contract version')
    for field in ('plan_item','source_revision'):
        if not isinstance(c[field],str) or not c[field].strip(): raise ValueError('missing '+field)
    files(c['files'])
    if not isinstance(c['allowed_paths'],list) or len(c['allowed_paths'])>100: raise ValueError('invalid allowed paths')
    for x in c['allowed_paths']: path(x)
    if len(set(c['allowed_paths'])) != len(c['allowed_paths']): raise ValueError('duplicate allowed paths')
    if not isinstance(c['worker'],str) or len(c['worker'].encode())>32768: raise ValueError('invalid worker program')
    if not isinstance(c['checks'],dict) or not c['checks']: raise ValueError('protected checks required')
    files(c['checks'])
    if not all(k.endswith('.py') for k in c['checks']): raise ValueError('checks must be Python programs')
    if type(c['timeout_seconds']) is not int or not 1<=c['timeout_seconds']<=300: raise ValueError('invalid deadline')
    if c['contract_sha256'] != digest({k:v for k,v in c.items() if k!='contract_sha256'}): raise ValueError('contract digest mismatch')
    return c

def inputs(c,dependencies):
    result=dict(c['files']); supplied=set()
    for job,receipt in sorted(dependencies.items()):
        if receipt.get('verification')!='accepted': raise ValueError('prerequisite not accepted')
        data=files(receipt['files'])
        if receipt.get('output_sha256')!=digest(data): raise ValueError('prerequisite digest mismatch')
        for k,v in data.items():
            if k in supplied and result[k]!=v: raise ValueError('conflicting prerequisite changes')
            result[k]=v; supplied.add(k)
    return files(result)
