"""A separate container for each prepare, implementation and verification stage."""
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
from contract import validate, inputs, files, digest, MAX_BYTES

BUNDLE=Path(os.environ.get('TASK_BUNDLE','/contract/bundle.json'))
WORK=Path(os.environ.get('TASK_WORK','/workspace'))

def snapshot(root):
    result={}
    for p in sorted(root.rglob('*')):
        if p.is_symlink(): raise ValueError('symlink output refused')
        if p.is_file():
            if p.stat().st_size>MAX_BYTES: raise ValueError('oversized file')
            result[p.relative_to(root).as_posix()]=p.read_text()
        elif not p.is_dir(): raise ValueError('nonregular output refused')
    return files(result)

def main(stage):
    b=json.loads(BUNDLE.read_text()); c=validate(b['contract']); baseline=inputs(c,b.get('dependency_outputs',{}))
    if stage=='prepare':
        for name,text in baseline.items():
            p=WORK/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
        return
    if stage=='implement':
        # No scheduler credentials, service account token, or inherited event fd.
        r=subprocess.run([sys.executable,'-B','-c',c['worker']],cwd=WORK,
             env={'PATH':os.environ['PATH'],'HOME':'/tmp','PYTHONDONTWRITEBYTECODE':'1'},timeout=c['timeout_seconds'])
        sys.exit(r.returncode)
    if stage!='verify': raise ValueError('unknown stage')
    data=snapshot(WORK)
    changed={k for k in baseline.keys() | data.keys() if baseline.get(k)!=data.get(k)}
    if not changed.issubset(set(c['allowed_paths'])): raise ValueError('change outside allowed paths')
    if any(k not in data for k in changed): raise ValueError('deletion requires a separate contract version')
    # Verify a copied artifact; check execution cannot alter the retained artifact.
    target=Path('/tmp/verified-source');shutil.copytree(WORK,target)
    for name,program in sorted(c['checks'].items()):
        r=subprocess.run([sys.executable,'-B','-c',program],cwd=target,
          env={'PATH':os.environ['PATH'],'HOME':'/tmp','PYTHONDONTWRITEBYTECODE':'1'},
          capture_output=True,timeout=c['timeout_seconds'])
        if r.returncode: raise ValueError('acceptance check failed: '+name)
    emitted={k:data[k] for k in sorted(changed)}
    print(json.dumps({'verification':'accepted','contract_sha256':c['contract_sha256'],
      'output_sha256':digest(emitted),'files':emitted,'checks':[{'id':k,'status':'pass'} for k in sorted(c['checks'])]},sort_keys=True))

if __name__=='__main__':
    try: main(sys.argv[1])
    except Exception as e:
        print(json.dumps({'verification':'failed','reason':str(e)}),file=sys.stderr);sys.exit(3)
