"""Thin Addams-to-Kubernetes adapter. The generic runner retains lease ownership."""
import json
import os
from pathlib import Path
import signal
import ssl
import sys
import time
import urllib.error
import urllib.request
from contract import validate, inputs, digest

NS='development-workers'
TOKEN=REDACTED api(method,path,body=None):
    request=urllib.request.Request('https://kubernetes.default.svc'+path,
       data=json.dumps(body).encode() if body is not None else None,method=method,
       headers={'Authorization':'Bearer '+TOKEN.read_text(),'Content-Type':'application/json'})
    with urllib.request.urlopen(request,context=ssl.create_default_context(cafile=CA),timeout=15) as r:
        data=r.read(524289)
        if len(data)>524288: raise ValueError('oversized API response')
        return json.loads(data) if 'json' in r.headers.get('Content-Type','') else data.decode()

def job(name,image,bundle):
    security={'allowPrivilegeEscalation':False,'readOnlyRootFilesystem':True,'capabilities':{'drop':['ALL']}}
    def container(stage):
        return {'name':stage,'image':image,'imagePullPolicy':'IfNotPresent',
          'command':['python','/app/development/task.py',stage], 'securityContext':security,
          'resources':{'requests':{'cpu':'100m','memory':'64Mi'},'limits':{'cpu':'1','memory':'256Mi'}},
          'volumeMounts':[{'name':'work','mountPath':'/workspace'},
            {'name':'contract','mountPath':'/contract','readOnly':True},{'name':'tmp','mountPath':'/tmp'}]}
    return {'apiVersion':'batch/v1','kind':'Job','metadata':{'name':name,'namespace':NS,
      'labels':{'app':'development-task'}},'spec':{'backoffLimit':0,'activeDeadlineSeconds':480,
      'ttlSecondsAfterFinished':86400,'template':{'metadata':{'labels':{'app':'development-task'}},'spec':{
      'automountServiceAccountToken':False,'restartPolicy':'Never',
      'nodeSelector':{'kubernetes.io/hostname':'ci2'},
      'securityContext':{'runAsNonRoot':True,'runAsUser':10001,'runAsGroup':10001,'fsGroup':10001,'seccompProfile':{'type':'RuntimeDefault'}},
      'initContainers':[container('prepare'),container('implement')],'containers':[container('verify')],
      'volumes':[{'name':'work','emptyDir':{'sizeLimit':'16Mi'}},{'name':'tmp','emptyDir':{'sizeLimit':'32Mi'}},
       {'name':'contract','configMap':{'name':name}}]}}}}

def run(envelope):
    b=envelope['params']; c=validate(b['contract']);inputs(c,b.get('dependency_outputs',{}))
    image=os.environ['DEVELOPMENT_IMAGE']
    if '@sha256:' not in image: raise ValueError('executor image must be digest pinned')
    name='dev-'+envelope['attempt_id']; endpoint='/apis/batch/v1/namespaces/'+NS+'/jobs/'+name
    config='/api/v1/namespaces/'+NS+'/configmaps/'+name
    def stop(*args): raise InterruptedError('runner stopped this attempt')
    signal.signal(signal.SIGTERM,stop); signal.signal(signal.SIGINT,stop)
    created=False
    try:
        api('POST',config.rsplit('/',1)[0],{'apiVersion':'v1','kind':'ConfigMap','metadata':{'name':name,'namespace':NS},
          'immutable':True,'data':{'bundle.json':json.dumps(b)}})
        j=api('POST',endpoint.rsplit('/',1)[0],job(name,image,b)); created=True
        # Tie the input bundle to the Job's lifecycle; TTL removes both.
        api('PUT',config,{'apiVersion':'v1','kind':'ConfigMap','metadata':{'name':name,'namespace':NS,
          'ownerReferences':[{'apiVersion':'batch/v1','kind':'Job','name':name,'uid':j['metadata']['uid']}]},
          'immutable':True,'data':{'bundle.json':json.dumps(b)}})
        until=time.monotonic()+500
        while time.monotonic()<until:
            state=api('GET',endpoint).get('status',{})
            if state.get('failed'): raise ValueError('execution or protected verification failed: '+name)
            if state.get('succeeded'):
                pods=api('GET','/api/v1/namespaces/'+NS+'/pods?labelSelector=job-name%3D'+name)['items']
                if len(pods)!=1: raise ValueError('ambiguous task pod')
                raw=api('GET','/api/v1/namespaces/'+NS+'/pods/'+pods[0]['metadata']['name']+'/log?container=verify&limitBytes=262144')
                result=json.loads(raw)
                if result.get('verification')!='accepted' or result.get('contract_sha256')!=c['contract_sha256']:
                    raise ValueError('invalid verification result')
                if result.get('output_sha256')!=digest(result['files']): raise ValueError('output digest mismatch')
                result['kubernetes_job']=name;result['executor_image']=image
                return result
            time.sleep(2)
        raise TimeoutError('task deadline exceeded')
    except BaseException:
        # Terminate the child Job on cancellation/lease loss; no unbounded orphan execution.
        if created:
            try: api('DELETE',endpoint,{'propagationPolicy':'Foreground'})
            except Exception: pass
        else:
            try: api('DELETE',config)
            except Exception: pass
        raise

if __name__=='__main__':
    try:
        output=run(json.load(sys.stdin))
        event={'type':'result','summary':'Protected checks accepted the bounded patch','output':output,'output_digest':output['output_sha256']}
        os.write(int(os.environ['JOB_EVENTS_FD']),(json.dumps(event)+'\n').encode())
    except Exception as e:
        print(str(e),file=sys.stderr);sys.exit(3 if isinstance(e,ValueError) else 75)
