import copy,json,os,subprocess,sys,tempfile,unittest
from pathlib import Path
from contract import digest,validate,inputs
from adapter import job

def contract(**changes):
    c={'version':1,'plan_item':'plan-authority','source_revision':'fixture-v1',
       'files':{'value.py':'answer = 0\n'},'allowed_paths':['value.py'],
       'worker':"from pathlib import Path; Path('value.py').write_text('answer = 42\\n')",
       'checks':{'answer.py':'from value import answer; assert answer == 42'},'timeout_seconds':5}
    c.update(changes);c['contract_sha256']=digest(c);return c

class ContractTests(unittest.TestCase):
    def test_modified_contract_rejected(self):
        c=contract();c['worker']='pass'
        with self.assertRaises(ValueError):validate(c)
    def test_empty_checks_rejected(self):
        with self.assertRaises(ValueError):validate(contract(checks={}))
    def test_paths(self):
        for name in ['/x','../x','a/../x','a//x','a\\b','.','a/./b']:
            with self.subTest(name=name),self.assertRaises(ValueError): validate(contract(files={name:'x'}))
    def test_boundaries(self):
        for change in [{'timeout_seconds':True},{'timeout_seconds':301},{'files':{'x':'x'*131073}},{'allowed_paths':['x','x']}]:
            with self.subTest(change=str(change)[:80]),self.assertRaises(ValueError):validate(contract(**change))
    def test_dependency_digest_and_conflict(self):
        r={'verification':'accepted','files':{'a':'x'},'output_sha256':digest({'a':'x'})}
        self.assertEqual(inputs(contract(),{'a':r})['a'],'x')
        bad=copy.deepcopy(r);bad['files']['a']='y'
        with self.assertRaises(ValueError):inputs(contract(),{'a':bad})
        bad['output_sha256']=digest(bad['files'])
        with self.assertRaises(ValueError):inputs(contract(),{'a':r,'b':bad})
        r['verification']='failed'
        with self.assertRaises(ValueError):inputs(contract(),{'a':r})
    def test_worker_has_no_token_or_credentials(self):
        s=job('test','image@sha256:'+'a'*64,{})['spec']['template']['spec']
        self.assertFalse(s['automountServiceAccountToken'])
        for c in s['initContainers']+s['containers']:
            self.assertNotIn('envFrom',c);self.assertNotIn('env',c)
            self.assertTrue(c['securityContext']['readOnlyRootFilesystem'])
        self.assertEqual([x['name'] for x in s['initContainers']],['prepare','implement'])
        self.assertEqual(s['containers'][0]['name'],'verify')
    def run_stage(self,c,stage,root):
        b=root/'bundle.json';b.write_text(json.dumps({'contract':c,'dependency_outputs':{}}))
        env={**os.environ,'TASK_BUNDLE':str(b),'TASK_WORK':str(root/'work')}
        return subprocess.run([sys.executable,str(Path(__file__).with_name('task.py')),stage],env=env,capture_output=True,text=True)
    def test_noop_cannot_pass_behavior_check(self):
        with tempfile.TemporaryDirectory() as d:
            root=Path(d);(root/'work').mkdir();c=contract(worker='pass')
            self.assertEqual(self.run_stage(c,'prepare',root).returncode,0)
            self.assertEqual(self.run_stage(c,'implement',root).returncode,0)
            r=self.run_stage(c,'verify',root)
            self.assertNotEqual(r.returncode,0)
    def test_scope_violation_and_symlink(self):
        for worker in ["open('other','w').write('oops')","import os; os.symlink('/etc/passwd','link')"]:
            with tempfile.TemporaryDirectory() as d:
                root=Path(d);(root/'work').mkdir();c=contract(worker=worker)
                self.run_stage(c,'prepare',root);self.run_stage(c,'implement',root)
                self.assertNotEqual(self.run_stage(c,'verify',root).returncode,0)

if __name__=='__main__':unittest.main()
