"""Real PostgreSQL failure tests; only the named synthetic container is reachable."""
import concurrent.futures,json,sys,unittest,uuid
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from contract import digest
from rehearse import sql

def q(x):return "'"+str(x).replace("'","''")+"'"
def spec():return {'contract_sha256':'a'*64,'plan_item':'synthetic-test','source_revision':'fixture-v1'}
def submit(key=None,deps=(),document=None):
    key=key or uuid.uuid4().hex
    return sql('SELECT addams.submit_development('+q(key)+','+q(json.dumps(document or spec()))+'::jsonb,ARRAY['+','.join(q(x) for x in deps)+']::uuid[]);').strip()
def state(j):return sql('SELECT status FROM addams.jobs WHERE id='+q(j)).strip()
def claim():
    return json.loads(sql("SELECT coalesce((SELECT row_to_json(j) FROM addams.claim_job('development','test',90) j),'{}'::json);").strip())
def complete(j,result=True):
    receipt={'output':{'verification':'accepted','files':{},'output_sha256':digest({})}} if result else {}
    return sql('SELECT addams.complete_job('+q(j['id'])+','+q(j['current_attempt_id'])+',NULL,'+q(json.dumps(receipt))+'::jsonb)').strip()

class DatabaseTests(unittest.TestCase):
    def setUp(self):
        # Isolated synthetic DB only. No live URL is accepted by the harness.
        sql('DELETE FROM addams.job_events; UPDATE addams.jobs SET current_attempt_id=NULL; DELETE FROM addams.job_attempts; DELETE FROM addams.jobs;')
    def test_hold_and_release(self):
        j=submit();self.assertEqual(claim(),{})
        sql('SELECT addams.release_development();');self.assertEqual(claim()['id'],j)
    def test_idempotency_and_changed_contract(self):
        key=uuid.uuid4().hex;a=submit(key);self.assertEqual(a,submit(key))
        c=spec();c['source_revision']='different'
        with self.assertRaises(RuntimeError):submit(key,document=c)
    def test_missing_dependency_denied(self):
        with self.assertRaises(RuntimeError):submit(deps=[str(uuid.uuid4())])
    def test_parallel_claims_unique(self):
        ids={submit() for _ in range(6)};sql('SELECT addams.release_development();')
        with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
            claims=list(pool.map(lambda _:claim(),range(6)))
        self.assertEqual({x['id'] for x in claims},ids)
        self.assertEqual(claim(),{})
    def test_dependency_barrier(self):
        a=submit();b=submit();c=submit(deps=[a,b]);sql('SELECT addams.release_development();')
        one,two=claim(),claim();self.assertEqual(claim(),{})
        complete(one);sql('SELECT addams.release_development();');self.assertEqual(claim(),{})
        complete(two);sql('SELECT addams.release_development();');self.assertEqual(claim()['id'],c)
    def test_false_success_blocks_child(self):
        a=submit();b=submit(deps=[a]);sql('SELECT addams.release_development();')
        complete(claim(),False);sql('SELECT addams.release_development();');self.assertEqual(state(b),'cancelled')
    def test_expired_lease_rejected_and_reclaimed(self):
        a=submit();sql('SELECT addams.release_development();');old=claim()
        sql('UPDATE addams.jobs SET lease_expires_at=now()-interval \'1 second\' WHERE id='+q(a))
        self.assertEqual(complete(old),'f');new=claim();self.assertEqual(new['attempt_count'],2)
        self.assertNotEqual(old['current_attempt_id'],new['current_attempt_id'])
        self.assertEqual(complete(old),'f');self.assertEqual(complete(new),'t')
        self.assertEqual(complete(new),'f')
    def test_exhaustion_cancels_descendant(self):
        a=submit();b=submit(deps=[a]);sql('SELECT addams.release_development();')
        for _ in range(2):
            claim();sql('UPDATE addams.jobs SET lease_expires_at=now()-interval \'1 second\' WHERE id='+q(a))
        self.assertEqual(claim(),{});self.assertEqual(state(a),'failed')
        sql('SELECT addams.release_development();');self.assertEqual(state(b),'cancelled')
    def test_cancelled_attempt_cannot_complete(self):
        a=submit();sql('SELECT addams.release_development();');j=claim()
        sql('SELECT addams.cancel_job('+q(a)+')');self.assertEqual(complete(j),'f')
    def test_runtime_cannot_admit_or_edit_jobs(self):
        with self.assertRaises(RuntimeError):sql('SET ROLE runner_ledger; SELECT addams.submit_development(\'forged\','+q(json.dumps(spec()))+'::jsonb);')
        with self.assertRaises(RuntimeError):sql('SET ROLE runner_ledger; UPDATE addams.jobs SET status=\'completed\';')
        sql('SET ROLE runner_ledger; SELECT addams.release_development();')

if __name__=='__main__':unittest.main()
