const states=new Set(['pending','running','completed','failed','cancelled','waiting_dependencies','lease_expired','unverified_completion']);
export function parseDevelopment(value:unknown):Feedback|null {
 const x=value as Feedback;
 const text=(s:unknown):s is string=>typeof s==='string'&&s.length>0&&s.length<20000;
 if(!x||x.schema_version!==1||!text(x.observed_at)||!Number.isFinite(Date.parse(x.observed_at))||!text(x.source)||!text(x.coverage)||!Array.isArray(x.jobs)||x.jobs.length>1000||!Array.isArray(x.blockers)||x.blockers.length>100||!x.counts||typeof x.counts!=='object')return null;
