"""Publish a docker-save artifact with credentials kept on the operator machine.

Uses the registry's standard blob/manifest API; no remote Docker credentials.
Only this repository's private deployment registry is accepted.
"""
import base64,gzip,hashlib,io,json,os,sys,tarfile,urllib.error,urllib.parse,urllib.request
HOST='100.83.165.79:3000'
REPO='monocloud/development'

def main(archive,tag):
    raw=os.environ['K3S_CI_REGISTRY_DOCKERCFG']
    try:cfg=json.loads(raw)
    except ValueError:cfg=json.loads(base64.b64decode(raw))
    auth=cfg.get('auths',cfg)[HOST]
    token=auth.get('auth') or base64.b64encode((auth['username']+':'+auth['password']).encode()).decode()
    base='http://'+HOST
    def request(method,url,body=None,media='application/octet-stream'):
        url=urllib.parse.urljoin(base,url)
        if urllib.parse.urlsplit(url).netloc!=HOST:raise ValueError('registry redirect leaves authorized host')
        req=urllib.request.Request(url,data=body,method=method,headers={'Authorization':'Basic '+token,'Content-Type':media})
        return urllib.request.urlopen(req,timeout=120)
    def blob(data,media):
        sha='sha256:'+hashlib.sha256(data).hexdigest()
        try:
            with request('HEAD',f'/v2/{REPO}/blobs/{sha}') as r: pass
        except urllib.error.HTTPError as e:
            if e.code!=404:raise
            with request('POST',f'/v2/{REPO}/blobs/uploads/',b'') as r:location=r.headers['Location']
            sep='&' if '?' in location else '?'
            with request('PUT',location+sep+'digest='+sha,data) as r: pass
        return {'mediaType':media,'size':len(data),'digest':sha}
    with tarfile.open(archive) as tar:
        m=json.load(tar.extractfile('manifest.json'))
        if len(m)!=1:raise ValueError('exactly one image required')
        config=blob(tar.extractfile(m[0]['Config']).read(),'application/vnd.docker.container.image.v1+json')
        layers=[]
        for name in m[0]['Layers']:
            data=tar.extractfile(name).read()
            if data[:2]!=b'\x1f\x8b':data=gzip.compress(data,mtime=0)
            layers.append(blob(data,'application/vnd.docker.image.rootfs.diff.tar.gzip'))
            print('Published layer',layers[-1]['digest'],flush=True)
    manifest={'schemaVersion':2,'mediaType':'application/vnd.docker.distribution.manifest.v2+json','config':config,'layers':layers}
    body=json.dumps(manifest,separators=(',',':')).encode()
    with request('PUT',f'/v2/{REPO}/manifests/{tag}',body,manifest['mediaType']) as r:
        expected='sha256:'+hashlib.sha256(body).hexdigest()
        if r.headers.get('Docker-Content-Digest')!=expected:raise ValueError('manifest digest mismatch')
    print(HOST+'/'+REPO+'@'+expected)
if __name__=='__main__':main(*sys.argv[1:])
