"""Boss-side admission: validate a typed contract, then submit through one ledger.

Database credentials stay in environment; no credential appears in argv or output.
"""
import argparse,json,os,subprocess,sys,urllib.parse
from pathlib import Path
from contract import validate

def query(body,env_name='SUPABASE_DB_URL'):
    u=urllib.parse.urlsplit(os.environ[env_name]);env={**os.environ,
       'PGHOST':u.hostname,'PGPORT':str(u.port or 5432),'PGUSER':urllib.parse.unquote(u.username),
       'PGPASSWORD':urllib.parse.unquote(u.password),'PGDATABASE':u.path.lstrip('/'),'PGSSLMODE':'require','PGCONNECT_TIMEOUT':'10'}
    r=subprocess.run(['psql','-X','-qAt','-v','ON_ERROR_STOP=1'],env=env,input=body,text=True,capture_output=True,timeout=45)
    if r.returncode:raise RuntimeError('Ledger rejected operation: '+r.stderr[-1000:])
    return r.stdout.strip()

def literal(x):return "'"+str(x).replace("'","''")+"'"

def main():
    p=argparse.ArgumentParser();p.add_argument('contract',type=Path);p.add_argument('--key',required=True);p.add_argument('--after',action='append',default=[]);a=p.parse_args()
    import uuid
    for d in a.after:uuid.UUID(d)
    c=validate(json.loads(a.contract.read_text()))
    print(query('SELECT addams.submit_development('+literal(a.key)+','+literal(json.dumps(c))+'::jsonb,ARRAY['+','.join(literal(d) for d in a.after)+']::uuid[]);'))
if __name__=='__main__':main()
