"""Prepare a reproducible fork/join development package; never silently submit it."""
import json,sys
from pathlib import Path
from contract import digest

def make(files,allowed,worker,checks,revision):
    c={'version':1,'plan_item':'plan-authority','source_revision':revision,'files':files,
       'allowed_paths':allowed,'worker':worker,'checks':checks,'timeout_seconds':30}
    c['contract_sha256']=digest(c);return c

def build(out,revision):
    base={'totals.py':'def total(values):\n    return 0\n','formatting.py':'def describe(value):\n    return "unknown"\n'}
    items={
      'total':make(base,['totals.py'],"import time; time.sleep(8); from pathlib import Path; Path('totals.py').write_text('def total(values):\\n    return sum(values)\\n')",{'totals.py':"from totals import total; assert total([2,3])==5; assert total([])==0; assert total([-2,3])==1"},revision),
      'format':make(base,['formatting.py'],"import time; time.sleep(8); from pathlib import Path; Path('formatting.py').write_text('def describe(value):\\n    return f\"Total: {value}\"\\n')",{'formatting.py':"from formatting import describe; assert describe(5)=='Total: 5'; assert describe(0)=='Total: 0'"},revision),
      'join':make(base,[],'pass',{'integration.py':"from totals import total; from formatting import describe; assert describe(total([2,3]))=='Total: 5'"},revision),
      'false-success':make(base,[],'pass',{'wrong.py':'from totals import total; assert total([2,3])==5'},revision)}
    out.mkdir(parents=True,exist_ok=True)
