/** Existing Supabase identity, scoped to a pinned operator; no account migration.
 * Auth API verifies every token and supplies current trusted app_metadata.
 * User metadata, email matches and the JWT database role never grant access.
 */
import { escapeHtml } from '@dark/shared';
import { decodeJwt } from 'jose';
import type { WorkosConfig, WorkosEnv } from './config';
import { clearCookie, html, readCookie, redirect, safeNextPath, setCookie } from './http-util';
import { boundedText } from './internal-api-client';
import { errorPage, shell } from './pages';
import { matchRoute } from './route-registry';
import { randomToken, seal, timingSafeEqual, unseal } from './seal';
import type { ActiveSession, SessionLookup } from './session';
import { guardedPost } from './write-guard';

export const OPERATOR_COOKIE = '__Host-praxis_operator';
const LOGIN_COOKIE = '__Host-praxis_operator_login';
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
type Stored = { token: string; expires: number };
type LoginState = { nonce: string; next: string; expires: number };

export function isOperatorPath(path: string, method = 'GET'): boolean {
  const route = matchRoute(path, method);
  return route?.auth === 'admin' || (route?.auth === 'pane' && route.pane === 'operator');
}
export function usesOperatorAuth(request: Request, url: URL): boolean {
  return isOperatorPath(url.pathname, request.method) || url.pathname === '/operator/login'
    || (url.pathname === '/logout' && !!readCookie(request, OPERATOR_COOKIE))
    || (url.pathname === '/login' && isOperatorPath(new URL(safeNextPath(url.searchParams.get('next'), url.origin), url.origin).pathname));
}
export function operatorConfig(env: WorkosEnv, base: WorkosConfig): WorkosConfig | null {
  try {
    const url = new URL(env.SUPABASE_URL ?? '');
    const key = env.SUPABASE_PUBLISHABLE_KEY ?? '';
    if (url.protocol !== 'https:' || url.username || url.password || url.search || url.hash || url.pathname !== '/' || !key || !UUID.test(env.PRAXIS_OPERATOR_SUBJECT ?? '') || !base.adminOrgId) return null;
    // Refuse accidental placement of a privileged service key.
    if (!key.startsWith('sb_publishable_') && decodeJwt(key).role !== 'anon') return null;
    return { ...base, operatorAuth: { url: url.origin, publishableKey: key, subject: env.PRAXIS_OPERATOR_SUBJECT! } };
  } catch { return null; }
}
async function authRequest(config: WorkosConfig, path: string, token?: string, body?: unknown): Promise<Response> {
  const c = config.operatorAuth;
  if (!c) throw new Error('operator identity is not configured');
  return fetch(`${c.url}/auth/v1/${path}`, {
    method: body === undefined ? 'GET' : 'POST',
    headers: { apikey: c.publishableKey, ...(token ? { Authorization: `Bearer ${token}` } : {}), 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body), redirect: 'error', signal: AbortSignal.timeout(8000),
  });
}
async function identity(token: string, config: WorkosConfig): Promise<ActiveSession | null> {
  let claims;
  try { claims = decodeJwt(token); } catch { return null; }
  if (claims.iss !== `${config.operatorAuth?.url}/auth/v1` || claims.aud !== 'authenticated' || typeof claims.exp !== 'number' || claims.exp <= Date.now()/1000 || !UUID.test(String(claims.session_id ?? ''))) return null;
  const response = await authRequest(config, 'user', token);
  if (response.status === 401 || response.status === 403) return null;
  if (!response.ok) throw new Error('operator identity service unavailable');
  const user = JSON.parse(await boundedText(response.body, 65536));
  if (user.id !== claims.sub || user.id !== config.operatorAuth?.subject || user.app_metadata?.role !== 'admin' || !user.email_confirmed_at || user.is_anonymous === true) return null;
  return { claims: { sub: user.id, sid: String(claims.session_id), orgId: config.adminOrgId, role: 'admin' }, email: typeof user.email === 'string' ? user.email : null, accessToken: token, refreshToken: '' };
}
export async function loadOperatorSession(request: Request, config: WorkosConfig): Promise<SessionLookup> {
  const raw = readCookie(request, OPERATOR_COOKIE);
  if (!raw) return { kind: 'none', setCookies: [] };
  const stored = await unseal<Stored>(raw, config.sessionPassword, OPERATOR_COOKIE);
  const session = stored && typeof stored.token === 'string' && Number.isFinite(stored.expires) && stored.expires > Date.now() ? await identity(stored.token, config) : null;
  return session ? { kind: 'active', session, setCookies: [] } : { kind: 'none', setCookies: [clearCookie(OPERATOR_COOKIE)] };
}
const failure = (status: number, message: string) => html(errorPage('Operator sign-in', message), status);
export async function operatorLogin(request: Request, url: URL, config: WorkosConfig): Promise<Response> {
  if (request.method === 'GET' || request.method === 'HEAD') {
    const candidate = safeNextPath(url.searchParams.get('next'), url.origin);
    const next = isOperatorPath(new URL(candidate, url.origin).pathname) ? candidate : '/operator';
    const state: LoginState = { nonce: randomToken(), next, expires: Date.now()+600000 };
    const cookie = await seal(state, config.sessionPassword, LOGIN_COOKIE);
    return html(shell('Operator sign-in — Praxis', `<main class="narrow auth-state" id="main"><h1>Operator sign-in</h1><p>Use your existing administrator account to return to the workbench.</p><form method="post" action="/operator/login"><input type="hidden" name="csrf" value="${escapeHtml(state.nonce)}"><p><label>Email<br><input name="email" type="email" autocomplete="username" required></label></p><p><label>Password<br><input name="password" type="password" autocomplete="current-password" required></label></p><button type="submit">Open workbench</button></form></main>`), 200, [setCookie(LOGIN_COOKIE, cookie, 600)]);
  }
  if (request.method !== 'POST') return failure(405, 'Use the sign-in form.');
  if (request.headers.get('Origin') !== url.origin || !request.headers.get('Content-Type')?.startsWith('application/x-www-form-urlencoded')) return failure(403, 'Start sign-in from this application.');
  let form;
  try { form = new URLSearchParams(await boundedText(request.body, 8192)); } catch { return failure(413, 'Sign-in form is too large.'); }
  const raw = readCookie(request, LOGIN_COOKIE);
  const state = raw ? await unseal<LoginState>(raw, config.sessionPassword, LOGIN_COOKIE) : null;
  if (!state || !Number.isFinite(state.expires) || state.expires < Date.now() || typeof state.nonce !== 'string' || !timingSafeEqual(state.nonce, form.get('csrf') ?? '') || [...form.keys()].some(k => !['csrf','email','password'].includes(k)) || ['csrf','email','password'].some(k => form.getAll(k).length !== 1) || !form.get('email') || !form.get('password')) return failure(403, 'This sign-in form expired. Start sign-in again.');
  const result = await authRequest(config, 'token?grant_type=password', undefined, { email: form.get('email'), password: form.get('password') });
  if (result.status >= 400 && result.status < 500) return failure(401, 'Sign-in was not accepted. Check your account details and try again.');
  if (!result.ok) return failure(503, 'Sign-in is temporarily unavailable.');
  const body = JSON.parse(await boundedText(result.body, 65536));
  if (typeof body.access_token !== 'string') return failure(503, 'Sign-in could not be verified.');
  const session = await identity(body.access_token, config);
  if (!session) return failure(403, 'This account does not have operator access.');
  const exp = decodeJwt(body.access_token).exp as number;
  const expires = Math.min(exp*1000, Date.now()+3600000);
  const cookie = await seal({ token: body.access_token, expires }, config.sessionPassword, OPERATOR_COOKIE);
  if (cookie.length > 3800) return failure(503, 'Sign-in could not be saved.');
  const next = safeNextPath(state.next, url.origin);
  return redirect(isOperatorPath(new URL(next,url.origin).pathname) ? next : '/operator', 303, [setCookie(OPERATOR_COOKIE,cookie,Math.floor((expires-Date.now())/1000)),clearCookie(LOGIN_COOKIE)]);
}
export async function operatorLogout(request: Request, url: URL, config: WorkosConfig): Promise<Response> {
  const raw = readCookie(request, OPERATOR_COOKIE);
  const stored = raw ? await unseal<Stored>(raw,config.sessionPassword,OPERATOR_COOKIE) : null;
  let claims;
  try { claims = stored ? decodeJwt(stored.token) : null; } catch { claims = null; }
  const guard = await guardedPost({ request,url,claims: claims && typeof claims.sub==='string' ? {sub:claims.sub,sid:typeof claims.session_id==='string'?claims.session_id:null}:null,sessionPassword:config.sessionPassword },{csrf:'required',purpose:'logout',origin:'exact',contentType:'urlencoded',cap:{unit:'bytes',max:4096}});
  if (!guard.ok) return failure(403,'Sign out from the workbench.');
  if (stored) {
    const result = await authRequest(config,'logout?scope=local',stored.token,{});
    if (!result.ok && result.status!==401 && result.status!==403) return failure(503,'Sign-out could not be confirmed. Try again.');
  }
  return redirect('/operator/login',303,[clearCookie(OPERATOR_COOKIE),clearCookie(LOGIN_COOKIE)]);
}
